import * as React from "react"

function Home({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="home"
      className={className}
      {...props}
    >
      <style>{"body {
            margin: 0;
            font-family: 'Poppins', sans-serif;
            background-color: #1a2b3c;
            color: #ffffff;
        }
        .container {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 20px;
        }
        .logo {
            display: flex;
            align-items: center;
        }
        .logo img {
            width: 40px;
            margin-right: 10px;
        }
        .nav {
            display: flex;
            gap: 20px;
        }
        .nav a {
            color: #ffffff;
            text-decoration:#f1c40f;
            font-weight: 700;
            opacity: 0.2;
            transition: 1s;
        }
        .nav a:hover{
           opacity:1 ;
            color: #f1c40f;

        }
        .subscribe-section {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 50px;
        }
        .subscribe-text {
            max-width: 50%;
        }
        .subscribe-text h1 {
            font-size: 48px;
            color: #f1c40f;
        }
        .subscribe-text p {
            font-size: 18px;
            margin: 20px 0;
        }
        .subscribe-form {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }
        .subscribe-form input {
            padding: 10px;
            border: none;
            border-radius: 5px;
            font-size: 16px;
        }
        .subscribe-form button {
            padding: 10px;
            background-color: #f1c40f;
            border: none;
            border-radius: 5px;
            font-size: 16px;
            font-weight: 700;
            cursor: pointer;
        }
        .subscribe-image {
            position: relative;
        }
        .subscribe-image img {
            border-radius: 20px;
            width: 400px;
        }
            .background-shape {
            position: absolute;
            top: 0;
            right: 0;
            width: 100%;
            height: 100%;
            background-size: cover;
            border-radius: 20px;
            z-index: -1;
        }
        .icon {
            position: absolute;
            width: 50px;
            height: 50px;
        }
        .icon-1 {
            top: 20px;
            left: 20px;
        }
        .icon-2 {
            bottom: 20px;
            left: 20px;
        }
        .icon-3 {
            top: 20px;
            right: 20px;
        }"}</style>
      <div className="container">
          <div className="logo">
            <img src="images.png" alt="" />
            <span>
              Creative Marketing
            </span>
          </div>
          <div className="nav">
            <a href="#">
              Home
            </a>
            <a href="#">
              Services
            </a>
            <a href="#">
              Blog
            </a>
            <a href="#">
              About
            </a>
            <a href="#">
              FAQ
            </a>
          </div>
        </div>
        <div className="subscribe-section">
          <div className="subscribe-text">
            <h1>
              Subscribe Now to Our Newsletter
            </h1>
            <p>
              Stay updated with our latest news and offers. Enter your email below to subscribe to our newsletter.
            </p>
            <div className="subscribe-form">
              <input placeholder="Name" type="text" />
              <input placeholder="Email" type="email" />
              <button>
                Subscribe
              </button>
            </div>
          </div>
          <div className="subscribe-image">
            <img src="images.png" alt="" />
            <div className="background-shape">
            </div>
          </div>
      </div>
    </div>
  )
}

export { Home }
